  "check_code": "from pathlib import Path
import sqlite3


TARGET_CASE_ID = "CASE-EQ-2024-005"
EXPECTED_NEW_STEP_ID = "STEP-EQ-2024-005-04"

HISTORICAL_STEPS = [
    (
        "STEP-EQ-005-01",
        TARGET_CASE_ID,
        1,
        "成果受理",
