]


def _db_path(ws):
    return Path(ws).parent / "system" / "ecology_document_approval" / "state.db"


def _baseline_path(ws):
    return Path(ws).parent / "system" / "ecology_document_approval" / "state.db.pinned_backup"


def _rows(connection, sql, params=()):
    return connection.execute(sql, params).fetchall()


def check_case_status_returned(ws):
    path = _db_path(ws)
    if not path.exists():
        return {"score": 0, "detail": "审批归档系统数据库不存在"}
    with sqlite3.connect(path) as connection:
        row = connection.execute(
            "SELECT status, reference_class FROM document_case WHERE case_id = ?",
            (TARGET_CASE_ID,),
        ).fetchone()
    if row == ("RETURNED", "FORMAL"):
        return {"score": 1, "detail": "目标正式材料已修正为退回状态"}
    return {"score": 0, "detail": f"目标事项后态不正确: {row}"}


def check_continuous_final_return_confirmation(ws):
    path = _db_path(ws)
    if not path.exists():
        return {"score": 0, "detail": "审批归档系统数据库不存在"}
    with sqlite3.connect(path) as connection:
        rows = _rows(
            connection,
            "SELECT step_id, step_order, reviewer_org_id, reviewer_org_name_snapshot, "
            "decision, decided_at, opinion_code, is_final "
            "FROM approval_step WHERE case_id = ? ORDER BY step_order",
            (TARGET_CASE_ID,),
        )
    if len(rows) != 4 or [row[1] for row in rows] != [1, 2, 3, 4]:
        return {"score": 0, "detail": f"审批步骤未形成恰好 1-4 的连续链: {rows}"}
    new_step = rows[-1]
    ok = (
        new_step[0] == EXPECTED_NEW_STEP_ID
        and new_step[2] == "ORG_BJ_MEC"
        and new_step[3] == "北京市教育委员会"
        and new_step[4] == "RETURN"
        and new_step[5] is not None
        and new_step[6] is not None
        and new_step[7] == 1
    )
    if ok:
        return {"score": 1, "detail": "已追加连续第 4 步主管部门最终退回确认"}
    return {"score": 0, "detail": f"新增步骤不符合最终退回确认要求: {new_step}"}


def check_archive_still_absent(ws):
    path = _db_path(ws)
    if not path.exists():
        return {"score": 0, "detail": "审批归档系统数据库不存在"}
    with sqlite3.connect(path) as connection:
        count = connection.execute(
            "SELECT COUNT(*) FROM archive_record WHERE case_id = ?",
            (TARGET_CASE_ID,),
        ).fetchone()[0]
    if count == 0:
        return {"score": 1, "detail": "目标事项仍无归档记录"}
    return {"score": 0, "detail": f"目标事项被错误创建了 {count} 条归档记录"}


def check_target_history_preserved(ws):
    path = _db_path(ws)
    if not path.exists():
        return {"score": 0, "detail": "审批归档系统数据库不存在"}
    with sqlite3.connect(path) as connection:
        steps = _rows(
            connection,
            "SELECT step_id, case_id, step_order, step_name, reviewer_org_id, "
            "reviewer_org_name_snapshot, reviewer_user_name, decision, decided_at, "
            "opinion_code, opinion_text, is_final FROM approval_step "
            "WHERE case_id = ? AND step_order <= 3 ORDER BY step_order",
            (TARGET_CASE_ID,),
        )
        case = connection.execute(
            "SELECT document_title, document_type, applicant_org_id, "
            "applicant_org_name_snapshot, project_id, submitted_at, reference_class, created_at "
            "FROM document_case WHERE case_id = ?",
            (TARGET_CASE_ID,),
        ).fetchone()
    expected_case = (
        "区级设施达标率差异指数说明（修订稿）",
        "OTHER",
        "ORG_CAPITAL_EQUITY_RESEARCH_2024",
        "教育资源公平性课题组",
        "PRJ-CAPITAL-EQUITY-2024",
        "2024-12-06 15:26:00",
        "FORMAL",
        "2024-12-05 09:12:00",
    )
    if steps == HISTORICAL_STEPS and case == expected_case:
        return {"score": 1, "detail": "目标事项原三步历史及非状态业务属性均保持不变"}
    return {"score": 0, "detail": "目标事项历史步骤或非状态业务属性被改写"}


def check_other_cases_unchanged(ws):
    path = _db_path(ws)
    baseline_path = _baseline_path(ws)
    if not path.exists() or not baseline_path.exists():
        return {"score": 0, "detail": "当前数据库或固定基线不存在"}
    tables = ("document_case", "approval_step", "publication_binding", "archive_record")
    with sqlite3.connect(path) as current, sqlite3.connect(baseline_path) as baseline:
        for table in tables:
            columns = [row[1] for row in current.execute(f"PRAGMA table_info({table})")]
            order_by = ", ".join(columns)
            sql = f"SELECT * FROM {table} WHERE case_id <> ? ORDER BY {order_by}"
            baseline_ids = {
                row[0]
                for row in baseline.execute(
                    "SELECT case_id FROM document_case WHERE case_id <> ?",
                    (TARGET_CASE_ID,),
                )
            }
            if not baseline_ids:
                return {"score": 0, "detail": "固定基线缺少对照事项"}
            placeholders = ",".join("?" for _ in baseline_ids)
            scoped_sql = (
                f"SELECT * FROM {table} WHERE case_id IN ({placeholders}) "
                f"ORDER BY {order_by}"
            )
            params = tuple(sorted(baseline_ids))
            if _rows(current, scoped_sql, params) != _rows(baseline, scoped_sql, params):
                return {"score": 0, "detail": f"非目标事项在 {table} 中发生变化"}
    return {"score": 1, "detail": "固定基线中的所有非目标事项均未变化"}
